// src/state/module-image-journal.ts
var JOURNAL_DIR2 = "lumirealm/module_image_journal";
var SCHEMA_VERSION2 = 1;
function journalPath2(moduleId) {
  return `${JOURNAL_DIR2}/${moduleId}.json`;
}
function isJournalFile2(v) {
  if (!v || typeof v !== "object")
    return false;
  const f = v;
  return f.schema_version === SCHEMA_VERSION2 && typeof f.moduleId === "string" && Array.isArray(f.imageIds) && (f.status === "active" || f.status === "pending_delete");
}
function userIdOpts2(userId) {
  return userId !== undefined ? { userId } : {};
}
async function writeJournalFile2(storage, userId, file) {
  await storage.setJson(journalPath2(file.moduleId), file, userIdOpts2(userId));
}
async function readModuleImageJournalFile(storage, userId, moduleId) {
  const file = await storage.getJson(journalPath2(moduleId), { fallback: null, ...userIdOpts2(userId) });
  return isJournalFile2(file) ? file : null;
}
async function appendModuleImageIdsToJournal(storage, userId, moduleId, newIds) {
  const cleanIds = newIds.filter((id) => typeof id === "string" && id.length > 0);
  if (cleanIds.length === 0)
    return;
  const existing = await readModuleImageJournalFile(storage, userId, moduleId);
  if (existing && existing.status === "pending_delete")
    return;
  const curIds = existing ? existing.imageIds : [];
  const merged = Array.from(new Set([...curIds, ...cleanIds]));
  if (existing && merged.length === curIds.length)
    return;
  await writeJournalFile2(storage, userId, {
    schema_version: SCHEMA_VERSION2,
    moduleId,
    imageIds: merged,
    status: "active",
    updated_at: Date.now()
  });
}
async function clearModuleImageJournal(storage, userId, moduleId) {
  try {
    await storage.delete(journalPath2(moduleId), userId);
  } catch {}
}
async function listModuleImageJournalIds(storage, userId) {
  let names;
  try {
    names = await storage.list(JOURNAL_DIR2, userId);
  } catch {
    return [];
  }
  const out = [];
  for (const name of names) {
    if (!name.endsWith(".json"))
      continue;
    out.push(name.replace(/\.json$/i, ""));
  }
  return out;
}

// src/state/orphan-detect.ts
var IMAGE_URL_RE = /\/api\/v1\/images\/([A-Za-z0-9_\-]+)/g;
function extractImageUrlIds(text) {
  if (typeof text !== "string" || text.length === 0)
    return [];
  const out = [];
  IMAGE_URL_RE.lastIndex = 0;
  let m;
  while ((m = IMAGE_URL_RE.exec(text)) !== null) {
    if (m[1] && m[1].length > 0)
      out.push(m[1]);
  }
  return out;
}
async function buildLiveImageIdSet(deps) {
  const liveIds = new Set;
  let liveCharacterRefs = 0;
  let liveModuleRefs = 0;
  let liveJournalRefs = 0;
  const addId = (id, bumpKind) => {
    if (typeof id !== "string" || id.length === 0)
      return;
    if (liveIds.has(id))
      return;
    liveIds.add(id);
    if (bumpKind === "char")
      liveCharacterRefs++;
    else if (bumpKind === "module")
      liveModuleRefs++;
    else
      liveJournalRefs++;
  };
  const characters = await deps.listLumirealmCharacters();
  for (const c of characters) {
    addId(c.image_id, "char");
    for (const entry of Object.values(c.asset_index ?? {})) {
      for (const id of entry.imageIds ?? [])
        addId(id, "char");
    }
    for (const entry of Object.values(c.emotion_index ?? {})) {
      for (const id of entry.imageIds ?? [])
        addId(id, "char");
    }
    for (const replace of c.regex_replace_strings ?? []) {
      for (const id of extractImageUrlIds(replace))
        addId(id, "char");
    }
    for (const id of extractImageUrlIds(c.background_html))
      addId(id, "char");
  }
  const modules = await deps.listModules();
  for (const m of modules) {
    for (const id of m.asset_imageIds)
      addId(id, "module");
  }
  const skippedJournalCharacters = [];
  const skippedJournalModules = [];
  const charJournals = await deps.listActiveCharacterJournals();
  for (const j of charJournals) {
    let exists = false;
    try {
      exists = await deps.characterExists(j.characterId);
    } catch {
      exists = false;
    }
    if (!exists) {
      skippedJournalCharacters.push(j.characterId);
      continue;
    }
    for (const id of j.imageIds)
      addId(id, "journal");
  }
  const moduleJournals = await deps.listActiveModuleJournals();
  for (const j of moduleJournals) {
    let exists = false;
    try {
      exists = await deps.moduleExists(j.moduleId);
    } catch {
      exists = false;
    }
    if (!exists) {
      skippedJournalModules.push(j.moduleId);
      continue;
    }
    for (const id of j.imageIds)
      addId(id, "journal");
  }
  return {
    liveIds,
    liveCharacterRefs,
    liveModuleRefs,
    liveJournalRefs,
    charactersScanned: characters.length,
    modulesScanned: modules.length,
    skippedJournalCharacters,
    skippedJournalModules
  };
}

// src/interpreter/dispatch.ts
var GENERATION_ENDED_BINDINGS = [
  "output"
];
// src/interpreter/risu-chat-view.ts
function buildRisuChatView(input) {
  const messages = input.messages.map((m) => ({ ...m }));
  const adjustments = [];
  let stripped = 0;
  while (messages.length > 0) {
    const last = messages[messages.length - 1];
    if (last.role === "assistant" && (!last.content || last.content === "")) {
      messages.pop();
      stripped++;
    } else {
      break;
    }
  }
  if (stripped > 0)
    adjustments.push(`stripped:${stripped}-trailing-empty-assistant`);
  let greeting;
  let greetingIndex;
  if (messages.length > 0 && messages[0].role !== "user") {
    greeting = messages[0].content;
    greetingIndex = messages[0].greetingIndex;
    messages.shift();
    adjustments.push("stripped:1-leading-greeting");
  }
  return greeting !== undefined ? {
    messages,
    adjustments,
    greeting,
    ...greetingIndex !== undefined ? { greetingIndex } : {}
  } : { messages, adjustments };
}

// src/interpreter/defaults-cache.ts
var byCharacter = new Map;
var chatToCharacter = new Map;
function setActiveScriptstateDefaults(chatId, characterId, defaults) {
  byCharacter.set(characterId, defaults);
  chatToCharacter.set(chatId, characterId);
}
function clearActiveScriptstateDefaults(chatId) {
  chatToCharacter.delete(chatId);
}
