    const rendered = toStr(resolve(rawValue, "value"));
    if (op === "=" || !op) {
      setVar(name, rendered);
      return;
    }
    const pN = Number(getVar(name));
    const pBase = Number.isFinite(pN) ? pN : 0;
    const nN = Number(rendered);
    const nBase = Number.isFinite(nN) ? nN : 0;
